class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.cache = {}
        self.freq_count = {}
        self.min_freq = 0

    def _update_freq(self, key):
        if key not in self.cache:
            return 0
        freq = self.freq_count[key]
        self.freq_count[key] += 1
        if freq == self.min_freq and len(self.cache) > maxsize:
            self._remove_least_frequent()
        return freq

    def _remove_least_frequent(self):
        oldest_key = next((k for k, v in iter(self.freq_count.items()) if v == self.min_freq), None)
        del self.cache[oldest_key]
        del self.freq_count[oldest_key]
        if not self.map:
            self.min_freq = 1

    def get(self, key):
        if key in self.cache:
            freq = self._update_freq(key)
            return self.cache[key]
        return -1

    def put(self, key, value):
        if key in self.cache:
            freq = self._update_freq(key)
            self.cache[key] = value
        else:
            if len(self.cache) == self.maxsize:
                self._remove_least_frequent()
            self.cache[key] = value
            self.freq_count[key] = 1
            self.min_freq = 1
