def extostr(e, max_level=30, max_path_level=5):
    result = f"{e.__class__.__name__}: {e.args[0]}"
    if max_level > 0 and not isinstance(e, ExceptionBase):
        exc_info = e.__traceback__.tb_next
        for i in range(max_level):
            if exc_info is None:
                break
            frame = exc_info.tb_frame
            file_name = frame.f_code.co_filename
            line_number = frame.f_lineno
            function_name = frame.f_code.co_name
            if function_name == '<module>':
                function_name = '<unknown>'
            result += f'\n  at {file_name} on line {line_number} in {function_name}'
            exc_info = exc_info.tb_next
    if max_path_level > 0 and isinstance(e, ExPathError):
        path = e.path
        if isinstance(path, list):
            path = '/'.join(path)
        result += f'\n  from {path}'
