import typing

from typing import AnyStr, Any, Dict, Iterable, List, Union, Tuple


class SQLParams:
    in_style: Union[int, str]


def formatmany(
    sql: AnyStr,
    many_params: Union[Iterable[Dict[str, Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[str, Any]], List[Sequence[Any]]]]:
    formatted_sql = sql.replace('%', '?')
    converted_params = []

    for params in many_params:
        if isinstance(params, dict):
            if SQLParams.in_style.isalpha():
                converted_params.append({k: v for k, v in params.items() if SQLParams.in_style in k})
            else:
                converted_params.append({k: v for k, v in params.items() if SQLParams.in_style <= k <= SQLParams.in_style + len(params) - 1})
        else:
            if SQLParams.in_style.isalpha():
                converted_params.append([v for v in params if SQLParams.in_style in v])
            else:
                converted_params.append([v for v in params if SQLParams.in_style <= v <= SQLParams.in_style + len(params) - 1])

    return formatted_sql, converted_params
