from ruamel.yaml.nodes import ScalarNode, MappingNode

def deep_merge_nodes(nodes):
    result = []
    seen_keys = set()

    for key, value in nodes:
        if isinstance(key, ScalarNode):
            if keytag in result:
                existing_value = next(value for _, existing_value in result if existing_value.tag == keytag)
                if isinstance(value, MappingNode):
                    existing_value.value.update(value.value)
                else:
                    if not isinstance(existing_value, MappingNode):
                        existing_value = MappingNode()
                        existing_value.value.extend(existing_value.value)
                    existing_value.tag = value.tag
                    existing_value.value.append(value)
            else:
                result.append((keytag, value))
            seen_keys.add(keytag)
        elif isinstance(key, MappingNode):
            if keytag in result:
                existing_key = next(key for _, existing_key in result if existing_key.tag == keytag)
                deep_merge_nodes(((existing_key.tag, existing_key), value)))
            else:
                result.append((keytag, key))
            seen_keys.add(keytag)
        else:
            raise ValueError(f"Unsupported node type: {type(key)}")

    return result
