import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    pos = 0
    words = []
    while True:
        match = re.search(r'[\w\W]+\b', s, re.IGNORECASE, pos=0)
        if match:
            word = match.group()
            pos = match.end()
            words.append(word)
            if match.group(0) == '}':
                break
        elif platform == 1:
            break
        elif platform == 0:
            break
        else:
            pos = len(s) + 1  # Skip rest of string
    return words
