    if iface not in provided_by:
        if tentative:
            # Skip the check if tentative is True
            return True
        raise Invalid(f"The candidate {candidate} does not claim to provide {iface}")

    for name, method in iface.getMethods():
        if not hasattr(candidate, name):
            raise Invalid(f"The candidate {candidate} does not define the method {name}")

    for name, attribute in iface.getAttributes():
        if not hasattr(candidate, name):
            raise Invalid(f"The candidate {candidate} does not define the attribute {name}")

