from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    if document.startswith("{"):
        # If JSON format, parse as JSON
        return json.loads(document)
    else:
        # If XRD format, parse as XRD
        # This is a simplified example and might not handle all XRD features fully
        result = {}
        current_section = None
        current_key = None
        for line in document.split('\n'):
            line = line.strip()
            if line.startswith("rel"):
                current_section = line.split(' ')[1]
                current_key = None
            elif current_section and line.startswith("name"):
                current_key = line.split(' ')[1]
            elif current_key:
                try:
                    parsed_value = eval(line)
                except Exception as e:
                    # Allow for commented-out values or values that are not evaluable
                    parsed_value = None
                result[current_section][current_key] = parsed_value
                current_key = None
        return result
